import{_ as i,l as d,o as a,c,v as o,p as s,x as r,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const O=JSON.parse('{"title":"O_DIRECT","description":"","frontmatter":{"title":"O_DIRECT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/direct-io.md","filePath":"cs/direct-io.md","lastUpdated":1789023840000}'),E={name:"cs/direct-io.md"};function _(h,e,D,m,I,C){const t=d("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="o-direct" tabindex="-1">O_DIRECT <a class="header-anchor" href="#o-direct" aria-label="Permalink to &quot;O_DIRECT&quot;">​</a></h1><div class="epigraph"><p>O_DIRECT 让读写尽量绕过页缓存，缓冲必须按设备与文件系统对齐；内核不再为你做那层统一帧。</p><footer>—— 据 Linux open(2) 对 O_DIRECT 的说明；数据库与 <em>OSTEP</em> 对双缓存问题的讨论</footer></div><p><a href="/cs/readahead">上一课</a>把页缓存用满。<a href="/cs/fs-mmap-coherence">mmap 一致</a> 的前提是「内核持有那一帧」。数据库、虚拟机盘后端常自己做缓冲池，再走内核会<strong>双缓存</strong>。缺口是 <code>O_DIRECT</code>：语义、对齐、与 fsync 的残余。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>open(..., O_DIRECT)</code>：<code>read</code>/<code>write</code> 用户缓冲直达块层（仍可能经 FS 映射成块号）。缓冲地址、长度、偏移通常需对齐到逻辑块。缺口：是否保证绕过所有缓存（控制器缓存仍在）；与同时 <code>mmap</code> 同一文件是否一致（Linux 不保证）；<code>O_DIRECT</code> 不是 <code>O_SYNC</code>——持久仍要 <a href="/cs/fsync">fsync</a> 或 <code>O_DSYNC</code>。本课不把 <code>io_uring</code> 注册缓冲提前写完。</p><p><span class="marginnote">对齐失败返回 EINVAL。文件系统可对 DIRECT 回退到缓冲 I/O——可移植程序不能假设绝对绕过。本课以 Linux 常见行为为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写：内核把用户页映射给块请求（或 bounce），不插入 inode 页树（或立即失效相关页）。读：DMA 进用户页。对照 <a href="/cs/tmpfs">tmpfs</a>：直接 I/O 对纯内存 FS 意义不同，常被拒绝或退化。对照 NFS：DIRECT 削弱客户端缓存，RPC 仍在。预读不适用于这条路径。</p>',8)),(a(),s(p,null,{default:r(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E7%94%A8%E6%88%B7%E5%AF%B9%E9%BD%90%E7%BC%93%E5%86%B2%22%5D%20--%3E%20OD%5B%22O_DIRECT%22%5D%0A%20%20OD%20--%3E%20FS%5B%22FS%20%E8%AF%91%E5%9D%97%E5%8F%B7%22%5D%0A%20%20FS%20--%3E%20BLK%5B%22%E5%9D%97%E5%B1%82%22%5D%0A%20%20PC%5B%22%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%20-.-%3E%7C%22%E4%B8%8D%E4%BD%9C%E4%B8%BA%E4%B8%BB%E5%89%AF%E6%9C%AC%22%7C%20OD%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>O_DIRECT 把「统一页缓存」从强制变成可选：应用愿承担对齐与失效，换回控制与内存。它不是更快的同义词——小请求会更慢。不要把本课写成存储产品的「直通」广告。与设备节点：对块设备同样适用，虚拟机常用。</p><p>一致性：混用缓冲 I/O 与 DIRECT 是未定义窗口；课序要求选一条主路径。</p><p>实现上：DIRECT 与缓冲 I/O 混用时，页缓存中的旧帧不会自动失效成应用以为的「盘上最新」。对齐要求随逻辑块与 DMA 限制变，文件系统可对未对齐请求回退，可移植程序必须处理 EINVAL。 读法上只引用<a href="/cs/readahead">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>O_DIRECT</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SCSI 保护信息、T10 DIF。不保证每台 NAS 的 DIRECT 语义。下一课把「等待完成」从同步 read 换成 POSIX 异步 I/O。</p><p>版本字段会变，课序钉的是机制对象「O_DIRECT」，不是某一主线内核的结构体名。 后课默认：可绕过页缓存，但要对齐且自管一致性。异步提交与完成队列，下一课 POSIX AIO。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>O_DIRECT 绕过（尽量）页缓存，要求对齐。</li><li>它不是 fsync；与 mmap 混用危险。</li><li>POSIX AIO 是下一课。</li><li>出处：Linux <code>open(2)</code>；<em>OSTEP</em>；Silberschatz <em>OSC</em> 对直接 I/O 的背景。</li></ul>',11))])}const f=i(E,[["render",_]]);export{O as __pageData,f as default};
